import {clone} from './model.js';
export function wavBlob(channels,sampleRate){const n=channels[0].length,buf=new ArrayBuffer(44+n*4),v=new DataView(buf);const str=(at,s)=>[...s].forEach((c,i)=>v.setUint8(at+i,c.charCodeAt(0)));str(0,'RIFF');v.setUint32(4,36+n*4,true);str(8,'WAVE');str(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,2,true);v.setUint32(24,sampleRate,true);v.setUint32(28,sampleRate*4,true);v.setUint16(32,4,true);v.setUint16(34,16,true);str(36,'data');v.setUint32(40,n*4,true);for(let i=0;i<n;i++)for(let c=0;c<2;c++){const x=Math.max(-1,Math.min(1,channels[c][i]));v.setInt16(44+(i*2+c)*2,x<0?x*32768:x*32767,true);}return new Blob([buf],{type:'audio/wav'});}
function impulse(ctx){const len=Math.floor(ctx.sampleRate*6),b=ctx.createBuffer(2,len,ctx.sampleRate);let seed=348981;for(let ch=0;ch<2;ch++){const d=b.getChannelData(ch);let prev=0;for(let i=0;i<len;i++){seed=(Math.imul(seed,1664525)+1013904223)>>>0;const n=seed/2147483648-1;prev=prev*.34+n*.66;d[i]=prev*Math.exp(-i/(ctx.sampleRate*1.15))*.6;}}return b;}
export function graph(ctx,node,p){const sum=ctx.createGain(),drums=ctx.createGain(),filter=ctx.createBiquadFilter();filter.type='lowpass';sum.connect(filter);const lfo=ctx.createOscillator(),motion=ctx.createGain();lfo.frequency.value=.043;lfo.connect(motion).connect(filter.frequency);lfo.start();const mix=p.mix.map((m,i)=>{const g=ctx.createGain(),pan=ctx.createStereoPanner(),f=ctx.createBiquadFilter();f.type='lowpass';f.frequency.value=i===5?p.patterns[p.activePattern].bass.cutoff:20000;node.connect(f,i);f.connect(g).connect(pan).connect(i===4?drums:sum);return{g,pan,f};});
 // Keep the percussion transient clear when the melodic filter closes.
 const bus=ctx.createGain(),effectsSend=ctx.createGain();filter.connect(bus);drums.connect(bus);filter.connect(effectsSend);drums.connect(effectsSend);const delayIn=ctx.createGain(),dl=ctx.createDelay(5),dr=ctx.createDelay(5),pl=ctx.createStereoPanner(),pr=ctx.createStereoPanner(),fb=ctx.createGain(),damp=ctx.createBiquadFilter();pl.pan.value=-.72;pr.pan.value=.72;damp.frequency.value=3200;effectsSend.connect(delayIn).connect(dl);dl.connect(pl).connect(bus);dl.connect(dr);dr.connect(pr).connect(bus);dr.connect(damp).connect(fb).connect(dl);
 const conv=ctx.createConvolver(),wet=ctx.createGain();conv.buffer=impulse(ctx);effectsSend.connect(conv);dl.connect(conv);dr.connect(conv);conv.connect(wet).connect(bus);
 const comp=ctx.createDynamicsCompressor();comp.threshold.value=-14;comp.knee.value=22;comp.ratio.value=4;comp.attack.value=.006;comp.release.value=.25;const master=ctx.createGain(),analyser=ctx.createAnalyser();analyser.fftSize=1024;bus.connect(comp).connect(master).connect(analyser);
 const g={ctx,node,mix,filter,drums,bus,effectsSend,lfo,motion,delayIn,dl,dr,fb,wet,master,analyser,comp};applyGraph(g,p,true);return g;}
export function applyGraph(g,p,initial=false){const time=g.ctx.currentTime;const set=(param,val)=>{if(initial)param.value=val;else param.setTargetAtTime(val,time,.035);};const solo=p.mix.some(m=>m.solo);p.mix.forEach((m,i)=>{set(g.mix[i].g.gain,m.mute||(solo&&!m.solo)?0:m.volume*(i===4?2:1));set(g.mix[i].pan.pan,m.pan);});set(g.mix[5].f.frequency,p.patterns[p.activePattern].bass.cutoff);set(g.mix[5].f.Q,1.1);set(g.filter.frequency,p.fx.cutoff);set(g.filter.Q,p.fx.resonance);set(g.motion.gain,p.fx.motion*p.fx.cutoff*.75);set(g.dl.delayTime,Math.min(4.8,60/p.tempo*p.fx.delayBeats));set(g.dr.delayTime,Math.min(4.8,60/p.tempo*p.fx.delayBeats));set(g.delayIn.gain,p.fx.delay*.6);set(g.fb.gain,p.fx.feedback);set(g.wet.gain,p.fx.reverb*.8);set(g.master.gain,p.master);}
export class Engine{
 constructor(onEvent){this.onEvent=onEvent;this.ready=false;this.soundfont=null;this.recording=false;}
 async init(p){if(this.ready){await this.ctx.resume();return;}if(this.loading)return this.loading;this.loading=this._init(p).catch(e=>{this.loading=null;this.ctx?.close();this.ctx=null;throw e;});return this.loading;}
 async _init(p){this.ctx=new AudioContext({latencyHint:'interactive'});await this.ctx.resume();const [_,__,buffer]=await Promise.all([this.ctx.audioWorklet.addModule('./processor.js'),this.ctx.audioWorklet.addModule('./recorder.js'),Promise.all([1,2].map(i=>fetch('./assets/generaluser-'+i+'.bin').then(r=>{if(!r.ok)throw Error('The soundfont could not load. Please retry.');return r.arrayBuffer();}))).then(parts=>{const joined=new Uint8Array(parts.reduce((n,b)=>n+b.byteLength,0));let at=0;for(const b of parts){joined.set(new Uint8Array(b),at);at+=b.byteLength;}return joined.buffer;})]);this.soundfont=buffer;this.node=new AudioWorkletNode(this.ctx,'circuit-synth',{numberOfInputs:0,numberOfOutputs:6,outputChannelCount:[2,2,2,2,2,2],processorOptions:{project:p,soundfont:buffer}});this.graph=graph(this.ctx,this.node,p);this.recorder=new AudioWorkletNode(this.ctx,'circuit-recorder',{outputChannelCount:[2]});this.graph.analyser.connect(this.recorder).connect(this.ctx.destination);this.chunks=[];this.recorder.port.onmessage=({data:d})=>{if(d.type==='chunk')this.chunks.push([d.l,d.r]);if(d.type==='done')this.finishRecording();};await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('Audio engine did not start. Please reload and try again.')),30000);this.node.port.onmessage=({data:d})=>{if(d.type==='ready'){clearTimeout(timer);resolve();}else if(d.type==='error'){clearTimeout(timer);reject(Error(d.message));this.onEvent(d);}else this.onEvent(d);};this.node.onprocessorerror=()=>{clearTimeout(timer);reject(Error('The audio processor stopped. Reload to restart it.'));this.onEvent({type:'error',message:'Audio processor stopped. Please reload.'});};});this.ready=true;this.ctx.onstatechange=()=>this.onEvent({type:'context',state:this.ctx.state});}
 update(p){if(this.ready){this.node.port.postMessage({type:'state',project:p});applyGraph(this.graph,p);}}
 async start(p){await this.init(p);this.update(p);this.node.port.postMessage({type:'start',project:p});}
 stop(){this.node?.port.postMessage({type:'stop'});}
 queue(index){this.node?.port.postMessage({type:'pattern',index});}
 preview(ch,note,source,velocity=85){if(this.ready)this.node.port.postMessage({type:'preview',ch,note,source,velocity});}
 async startRecording(p){await this.init(p);this.chunks=[];this.recording=true;this.recordStart=performance.now();this.recorder.port.postMessage('start');}
 stopRecording(){if(!this.recording)return;this.recording=false;this.recorder.port.postMessage('stop');return new Promise(r=>this.recordResolve=r);}
 finishRecording(){const len=this.chunks.reduce((n,c)=>n+c[0].length,0),l=new Float32Array(len),r=new Float32Array(len);let at=0;for(const c of this.chunks){l.set(c[0],at);r.set(c[1],at);at+=c[0].length;}this.chunks=[];const blob=wavBlob([l,r],this.ctx.sampleRate);this.recordResolve?.(blob);this.recordResolve=null;}
 async export(p,duration,onProgress){await this.init(p);const tail=8,sr=44100,ctx=new OfflineAudioContext(2,Math.ceil((duration+tail)*sr),sr);await ctx.audioWorklet.addModule('./processor.js');const node=new AudioWorkletNode(ctx,'circuit-synth',{numberOfInputs:0,numberOfOutputs:6,outputChannelCount:[2,2,2,2,2,2],processorOptions:{project:clone(p),soundfont:this.soundfont,autoplay:true,offline:true,duration}});const g=graph(ctx,node,p);g.master.gain.setValueAtTime(0,0);g.master.gain.linearRampToValueAtTime(p.master,.04);g.master.gain.setValueAtTime(p.master,duration+tail-3);g.master.gain.linearRampToValueAtTime(0,duration+tail);g.analyser.connect(ctx.destination);let failure;node.onprocessorerror=()=>failure=Error('The export audio processor stopped.');node.port.onmessage=({data:d})=>{if(d.type==='error')failure=Error(d.message);};const interval=setInterval(()=>onProgress?.(Math.min(.99,ctx.currentTime/(duration+tail))),150);try{const b=await ctx.startRendering();if(failure)throw failure;let peak=0;for(let ch=0;ch<2;ch++){const a=b.getChannelData(ch);for(let i=0;i<a.length;i++)peak=Math.max(peak,Math.abs(a[i]));}if(!Number.isFinite(peak))throw Error('Export contained invalid audio.');onProgress?.(1);return wavBlob([b.getChannelData(0),b.getChannelData(1)],sr);}finally{clearInterval(interval);node.disconnect();}}
}
